// Generated by "dolly install". Ambient dolly behavior for opencode, v1 and v2:
//   - task context injected into every model request
//   - a step auto-logged per finished turn
//   - turns mirrored to ~/.local/share/opencode/dolly/ for `dolly reindex`
// Every dolly shell-out swallows its errors: a missing dolly binary or store
// never blocks a session. Safe to delete; re-created on `dolly install`.
//
// One file, both plugin APIs, no dependency on an opencode package:
//   - opencode v2 reads the default export's `id` + `setup(ctx)` and registers
//     hooks on the context's domains (session, tool, event)
//   - opencode v1 reads the default export's `server()` (or, on older v1, the
//     named function export) and uses the hooks object it returns
import { execFile } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

/* ------------------------------ shared core ------------------------------ */

/** run dolly; resolves to stdout, or "" on any failure. stdin is always closed:
 *  `dolly hook …` reads it to EOF, and an open pipe would hang it */
function dolly(cwd, args, input = "") {
  return new Promise((resolve) => {
    try {
      const child = execFile("dolly", args, { cwd, encoding: "utf8", timeout: 15000 }, (err, stdout) =>
        resolve(err ? "" : String(stdout ?? "")),
      );
      child.stdin?.on("error", () => {});
      child.stdin?.end(input);
    } catch {
      resolve("");
    }
  });
}

/**
 * One message, whichever API produced it:
 *   v1 — `{ info: { id, role, time.created }, parts: [{ type: "text", text } | { type: "tool", tool, state.input }] }`
 *   v2 — `{ id, type: "user", text, time.created }` /
 *        `{ id, type: "assistant", content: [{ type: "text", text } | { type: "tool", name, state.input }] }`
 */
export function normalizeMessage(m) {
  const ms = (t) => (typeof t === "number" ? t : Date.parse(String(t ?? "")) || Date.now());
  const inputOf = (state) => (state && typeof state.input === "object" && state.input ? state.input : {});
  if (m && (m.info || Array.isArray(m.parts))) {
    const info = m.info ?? m;
    const parts = Array.isArray(m.parts) ? m.parts : [];
    return {
      role: String(info.role ?? ""),
      id: info.id,
      created: ms(info.time?.created),
      texts: parts.filter((p) => p?.type === "text" && typeof p.text === "string").map((p) => p.text),
      tools: parts.filter((p) => p?.type === "tool").map((p) => ({ name: String(p.tool ?? "tool"), input: inputOf(p.state) })),
    };
  }
  const type = String(m?.type ?? m?.role ?? "");
  const content = Array.isArray(m?.content) ? m.content : [];
  return {
    role: type,
    id: m?.id,
    created: ms(m?.time?.created),
    texts:
      type === "user"
        ? [m?.text].filter((s) => typeof s === "string")
        : content.filter((p) => p?.type === "text" && typeof p.text === "string").map((p) => p.text),
    tools: content.filter((p) => p?.type === "tool").map((p) => ({ name: String(p.name ?? p.tool ?? "tool"), input: inputOf(p.state) })),
  };
}

function createCore(cwd) {
  const injected = new Map(); // session → the context it was handed
  const turnStart = new Map(); // session → ms the current turn began
  const seen = new Map(); // session → messages already mirrored (idle refires)

  /**
   * The session-start text, computed once per session and then held steady:
   * it goes into the system prompt of EVERY request, and it carries clock-
   * relative bits ("updated 5m ago"), so refreshing it would rewrite the
   * prompt prefix and throw away the provider's cache on each turn. It is
   * re-read after a compaction — the same rhythm Claude Code's hook has.
   */
  async function context(sid) {
    const key = sid ? String(sid) : "";
    if (injected.has(key)) return injected.get(key);
    // the session id lets dolly name THIS conversation's task, not a recent one
    const text = (await dolly(cwd, ["hook", "session-start", "--raw"], JSON.stringify({ session_id: key }))).trim();
    if (text) injected.set(key, text);
    return text;
  }

  function compacted(sid) {
    injected.delete(sid ? String(sid) : "");
  }

  function newTurn(sid) {
    if (sid) turnStart.set(String(sid), Date.now());
  }

  // one line describing a tool call, for the work chain
  function describe(tool) {
    const input = tool.input;
    const file = input.filePath ?? input.file_path ?? input.path ?? input.notebook_path;
    if (/write|edit|patch/i.test(tool.name)) return typeof file === "string" ? path.basename(file) : tool.name;
    if (/bash|shell/i.test(tool.name) && typeof input.command === "string") {
      const line = input.command.split("\n").map((l) => l.trim()).find(Boolean);
      return line ? line.slice(0, 90) : tool.name;
    }
    if (/grep/i.test(tool.name)) return `${tool.name} ${String(input.pattern ?? "").slice(0, 60)}`;
    return tool.name;
  }

  function compress(chain, max = 60) {
    const out = [];
    let last = "";
    let run = 0;
    for (const item of chain) {
      if (item === last) {
        run++;
        continue;
      }
      if (last) out.push(run > 1 ? `${last} ×${run}` : last);
      last = item;
      run = 1;
    }
    if (last) out.push(run > 1 ? `${last} ×${run}` : last);
    return out.length <= max ? out : [...out.slice(0, max), `… +${out.length - max} more actions`];
  }

  function mirrorDir() {
    const base = process.env.DOLLY_OPENCODE_DIR || path.join(os.homedir(), ".local/share/opencode/dolly");
    return path.join(base, cwd.replace(/[^a-zA-Z0-9]/g, "-"));
  }

  /**
   * The turn that just ended = every message after the ones seen at the last
   * idle. Mirrored as one JSONL line in dolly's Segment shape (what `dolly
   * reindex` reads), then piped to `dolly hook stop --from-stdin` for auto-log.
   */
  async function finishTurn(sid, raw) {
    if (!Array.isArray(raw)) return;
    const msgs = raw.map(normalizeMessage);
    // `seen` lives in memory: after a restart start from the newest user
    // message, or the whole history would mirror as one turn
    let start = seen.get(sid);
    if (start === undefined || start > msgs.length) {
      start = 0;
      for (let i = msgs.length - 1; i >= 0; i--) {
        if (msgs[i].role === "user") {
          start = i;
          break;
        }
      }
    }
    seen.set(sid, msgs.length);
    const slice = msgs.slice(start);
    const user = slice.find((m) => m.role === "user");
    if (!user) return;

    const seg = {
      index: start + 1,
      uuid: String(user.id ?? `${sid}:${start}`),
      at: new Date(user.created).toISOString(),
      endedAt: new Date().toISOString(),
      prompt: slice.filter((m) => m.role === "user").flatMap((m) => m.texts).join("\n").trim(),
      files: [],
      commands: [],
      tools: {},
      assistantTexts: [],
      workChain: [],
      thinking: [],
      sidechains: 0,
    };
    for (const m of slice) {
      if (m.role === "assistant") for (const t of m.texts) if (t.trim()) seg.assistantTexts.push(t.trim());
      for (const tool of m.tools) {
        seg.tools[tool.name] = (seg.tools[tool.name] ?? 0) + 1;
        const action = describe(tool);
        if (action) seg.workChain.push(action);
        const file = tool.input.filePath ?? tool.input.file_path ?? tool.input.path;
        // only what the turn CHANGED: a read is not work
        if (/write|edit|patch/i.test(tool.name) && typeof file === "string") {
          const rel = path.isAbsolute(file) ? path.relative(cwd, file) : file;
          if (rel && !rel.startsWith("..") && rel !== ".dolly" && !rel.startsWith(".dolly/") && !seg.files.includes(rel)) {
            seg.files.push(rel);
          }
        }
        if (/bash|shell/i.test(tool.name) && typeof tool.input.command === "string") {
          const cmd = tool.input.command.slice(0, 160);
          if (cmd && !seg.commands.includes(cmd)) seg.commands.push(cmd);
        }
      }
    }
    seg.workChain = compress(seg.workChain);

    try {
      const dir = mirrorDir();
      fs.mkdirSync(dir, { recursive: true });
      fs.appendFileSync(path.join(dir, `${sid}.jsonl`), `${JSON.stringify({ ...seg, session: sid })}\n`);
    } catch {
      // the mirror is best-effort
    }

    await dolly(
      cwd,
      ["hook", "stop", "--from-stdin"],
      JSON.stringify({
        agent: "opencode",
        session: sid,
        // the user message id: stable across restarts, unlike a position
        turn: seg.uuid,
        turnStartMs: turnStart.get(sid) ?? user.created,
        text: seg.assistantTexts.join("\n"),
        tools: Object.keys(seg.tools),
        files: seg.files,
      }),
    );
  }

  return { context, compacted, newTurn, finishTurn };
}

/* ---------------------------------- v1 ----------------------------------- */

// v1 may find this plugin twice — the default export's server() and the
// legacy named export — so a directory registers its hooks once
const v1Loaded = new Set();

export async function DollyPlugin({ client, directory, worktree } = {}) {
  const cwd = worktree || directory || process.cwd();
  if (v1Loaded.has(cwd)) return {};
  v1Loaded.add(cwd);
  const core = createCore(cwd);

  /**
   * Display-only commands carry frontmatter "direct: true" and show their
   * output verbatim (/dolly-board) instead of having a model narrate it: the
   * first !`cmd` line runs as a session shell message, then we throw, which
   * skips the model call. If the shell route fails we stand down and the
   * normal prompt flow handles it. v2 has no global equivalent of
   * command.execute.before, so there those commands run through the model.
   */
  const DIRECT = new Map();
  function scanDirectCommands() {
    const cfgHome = process.env.XDG_CONFIG_HOME || path.join(os.homedir(), ".config");
    for (const dir of [path.join(cwd, ".opencode", "commands"), path.join(cfgHome, "opencode", "commands")]) {
      let files = [];
      try {
        files = fs.readdirSync(dir);
      } catch {
        continue;
      }
      for (const f of files) {
        if (!f.startsWith("dolly-") || !f.endsWith(".md")) continue;
        const name = f.slice(0, -3);
        if (DIRECT.has(name)) continue;
        let md = "";
        try {
          md = fs.readFileSync(path.join(dir, f), "utf8");
        } catch {
          continue;
        }
        if (!/^direct:[ ]*true[ ]*$/m.test(md)) continue;
        const start = md.indexOf("!`");
        const end = start === -1 ? -1 : md.indexOf("`", start + 2);
        if (end !== -1) DIRECT.set(name, md.slice(start + 2, end).trim());
      }
    }
  }

  /** $ARGUMENTS / ${ARGUMENTS:-default} / $1..$9, resolved before the shell sees them */
  function substituteArgs(tpl, args) {
    const list = args.trim() ? args.split(/\s+/) : [];
    let out = tpl;
    const DEF = "$" + "{ARGUMENTS:-";
    let idx;
    while ((idx = out.indexOf(DEF)) !== -1) {
      const end = out.indexOf("}", idx);
      const fallback = end === -1 ? "" : out.slice(idx + DEF.length, end);
      out = out.slice(0, idx) + (list[0] ?? fallback) + out.slice(end + 1);
    }
    out = out.split("$ARGUMENTS").join(args);
    for (let i = 9; i >= 1; i--) out = out.split("$" + i).join(list[i - 1] ?? "");
    return out;
  }

  async function runDirectCommand(input) {
    scanDirectCommands();
    const tpl = DIRECT.get(input.command);
    if (!tpl) return false;
    try {
      await client.session.shell({
        path: { id: input.sessionID },
        body: { command: substituteArgs(tpl, String(input.arguments ?? "")), agent: "build" },
      });
      return true;
    } catch {
      return false;
    }
  }

  return {
    "chat.message": async (input) => core.newTurn(input?.sessionID),
    "experimental.chat.system.transform": async (input, output) => {
      const ctx = await core.context(input?.sessionID);
      if (ctx) output.system.push(ctx);
    },
    "experimental.session.compacting": async (input, output) => {
      core.compacted(input?.sessionID); // time passed: the next request re-reads it
      const ctx = await core.context(input?.sessionID);
      if (ctx) output.context.push(ctx);
    },
    "command.execute.before": async (input) => {
      let handled = false;
      try {
        handled = await runDirectCommand(input);
      } catch {
        handled = false;
      }
      // a throw cancels the model call — the command already showed its output
      if (handled) throw new Error("dolly: display-only command");
    },
    event: async ({ event }) => {
      try {
        if (event?.type !== "session.idle") return;
        const sid = event.properties?.sessionID ?? event.properties?.info?.id;
        if (!sid) return;
        const res = await client.session.messages({ path: { id: String(sid) } });
        const data = res?.data;
        await core.finishTurn(String(sid), Array.isArray(data) ? data : (data?.messages ?? []));
      } catch {
        // never surface anything into the session
      }
    },
  };
}

/* ---------------------------------- v2 ----------------------------------- */

/**
 * opencode v2: hooks are registered on the context's domains.
 *   session "prompt"            a user turn begins
 *   session "context"           before every agent-loop model request — this
 *                               also covers the requests after a compaction,
 *                               which v1 needed a separate hook for
 *   session "compaction"        only to re-read the held context afterwards
 *   session "experimental.idle" the session finished its model work; the
 *                               `session.idle` event is the fallback when a
 *                               build does not offer that hook
 */
async function setup(ctx) {
  const cwd = ctx?.location?.directory || process.cwd();
  const core = createCore(cwd);
  const safe = (fn) => async (event) => {
    try {
      await fn(event);
    } catch {
      // never surface anything into the session
    }
  };
  const finish = async (sid) => {
    if (!sid) return;
    const messages = await ctx.session.context({ sessionID: String(sid) });
    await core.finishTurn(String(sid), Array.isArray(messages) ? [...messages] : []);
  };

  await ctx.session.hook("prompt", safe((event) => core.newTurn(event?.sessionID)));
  await ctx.session.hook(
    "context",
    safe(async (event) => {
      const text = await core.context(event?.sessionID);
      if (text && Array.isArray(event?.system)) event.system.push({ type: "text", text });
    }),
  );
  // a compaction is the one moment the held context is re-read
  await ctx.session.hook("compaction", safe((event) => core.compacted(event?.sessionID)));
  try {
    await ctx.session.hook("experimental.idle", safe((event) => finish(event?.sessionID)));
    return;
  } catch {
    // no idle hook in this build — follow the event stream instead
  }
  const controller = new AbortController();
  void (async () => {
    try {
      for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
        if (event?.type !== "session.idle") continue;
        await safe(finish)(event.data?.sessionID ?? event.properties?.sessionID ?? event.sessionID);
      }
    } catch {
      // stream closed
    }
  })();
  return () => controller.abort();
}

export default { id: "dolly", setup, server: DollyPlugin };
